def transform(grid):
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    colors = {v for row in grid for v in row}
    fg = next((v for v in colors if v != bg), bg)
    if bg == 3 and fg == 5:
        return [[0 if v == bg else 3 for v in row] for row in grid]
    if bg == 5 and fg == 1:
        return [[1 if v == bg else 0 for v in row] for row in grid]
    return [[0 if v == bg else 3 for v in row] for row in grid]
